const fs=require('fs'),ts=require('typescript'),assert=require('assert/strict');function load(file,deps={}){const m={exports:{}};new Function('require','module','exports',ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:1,target:9}}).outputText)(n=>{if(n in deps)return deps[n];throw Error('Unexpected dependency '+n)},m,m.exports);return m.exports;}
(async()=>{for(const [file,name,missing] of [['soft-delete','ensureSoftDeleteColumnProbed','deleted_at does not exist'],['product-code','ensureProductCodeColumnProbed','product_code does not exist']]){let reads=0;const api=load('src/lib/supabase/'+file+'.ts');const db={from:()=>({select:()=>({limit:async()=>{reads++;await new Promise(r=>setTimeout(r,10));return{error:null}}})})};assert.deepEqual(await Promise.all(Array.from({length:12},()=>api[name](db))),Array(12).fill(true));assert.equal(reads,1);await api[name](db);assert.equal(reads,1);const old=load('src/lib/supabase/'+file+'.ts');assert.equal(await old[name]({from:()=>({select:()=>({limit:async()=>({error:{message:missing}})})})}),false);}
let queries=0,selected='',filters=[],cookieReads=0,fail=false;const db={from:()=>{const chain={select(s){selected=s;return chain},eq(k,v){filters.push([k,v]);return chain},or(){return chain},order(){return chain},limit(){return chain},is(){return chain},then(resolve){queries++;return Promise.resolve(fail?{data:null,error:{message:'test failure'}}:{data:[{id:'one',name:'Dynasty Cream',brand:'Beauty of Joseon',slug:'dynasty-cream',sku:'8801',status:'active',image_url:'https://example.com/product.webp',price:999,source_row:null}],error:null}).then(resolve)}};return chain}};
const cache=(fn)=>{const entries=new Map();return(...args)=>{const key=JSON.stringify(args);if(!entries.has(key))entries.set(key,Promise.resolve(fn(...args)).catch(e=>{entries.delete(key);throw e}));return entries.get(key)}};
const search=load('src/lib/supabase/product-search.ts',{'next/cache':{unstable_cache:cache},'./product-search-filter':{buildProductSearchFilter:()=>''},'@/lib/product-images':{productHasRealImage:()=>true},'./config':{isSupabaseConfigured:()=>true},'./safe-server':{createSafeClient:()=>{cookieReads++;throw Error('Cookies in public cache')}},'./service':{createServiceClient:()=>db,createPublicClient:()=>db},'./soft-delete':{ensureSoftDeleteColumnProbed:async()=>true,isSoftDeleteColumnAvailable:()=>true},'./product-code':{ensureProductCodeColumnProbed:async()=>true,isProductCodeColumnAvailable:()=>true,isMissingProductCodeColumnError:()=>false},'@/lib/store/products-url':{getBrandFilterValue:x=>x,getDisplayBrandName:x=>x},'./products':{STATIC_PRODUCTS:[],STOREFRONT_PRODUCTS_CACHE_TAG:'storefront-products'},'@/lib/store/localized-product-name':{getLocalizedProductName:p=>p.name,withLocalizedNameFields:p=>p,containsHangul:()=>false,isKoreanLocale:()=>false}});
const first=await search.getSearchSuggestions('Dynasty Cream');await search.getSearchSuggestions('  DYNASTY CREAM  ');assert.equal(queries,1);assert.equal(first.products.length,1);assert.deepEqual(Object.keys(first.products[0]).sort(),['brand','id','name','sku','slug']);assert(!selected.includes('price'));assert(filters.some(([k,v])=>k==='status'&&v==='active'));assert.equal(cookieReads,0);await search.getSearchSuggestions('Dynasty Cream',8,'ko');assert.equal(queries,2);fail=true;await search.getSearchSuggestions('failure');await search.getSearchSuggestions('failure');assert.equal(queries,4);console.log('PASS cold schema probes coalesced 12→1; public suggestions reused across case variants; locales isolated; no cookies/prices; failed reads not cached.');})().catch(e=>{console.error(e);process.exitCode=1});
